/// <summary>
/// Return TAMRebateTable record from TAMRebateTrans
/// </summary>
/// <param name = "_forUpdate">Select for update</param>
/// <returns><c>TAMRebateTable</c> record</returns>
public TAMRebateTable METTAMRebateTable(boolean _forUpdate = false)
{
    return TAMRebateTable::find(this.RebateId, _forUpdate);
}

/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// Could not extend TAMRebateDateTrans.delete() as Hookable(false) nor cascadeDeleteRebateTrans as internal
/// When a rebateTrans is deleted and linked to METRebateScanSupplierTable, we need to update the corresponding flags
/// So we can reuse the transactions in the same or another rebate
/// </summary>
public void delete()
{
    ttsbegin;

    // Update external sales data provision or rebate processed to No
    METRebateScanSupplierTable::updateProcessedFlags(TAMRebateDateTrans::find(this.RebateTransId).RebateTransactionType, NoYes::No, this.RebateTransId, this.RefRecId);

    next delete();        

    ttscommit;        
}

/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// </summary>
/// <param name = "_externalSalesData"><t>METRebateScanSupplierTable</t></param>
public void metInitFromExternalSalesData(METRebateScanSupplierTable _externalSalesData)
{
    this.RebateRefAccount   = _externalSalesData.CustAccount;
    this.RebateRefId        = _externalSalesData.TransactionNumber;
    this.CurrencyCode       = _externalSalesData.CurrencyCode;
    this.ItemId             = _externalSalesData.ItemId;
    this.RebateRefQty       = _externalSalesData.SalesQty;
    this.RefUnitId          = _externalSalesData.UnitOfMeasure;
}
